// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        // Restrict putAmount to avoid extreme overflow cases; ensure caller is non-zero
        vm.assume(caller != address(0));
        vm.assume(putAmount <= 10 ether);
        vm.assume(collectAmount <= 10 ether);

        // Fund the contract for possible success of Collect
        vm.deal(address(c), 100 ether);

        // Perform Put from caller
        vm.prank(caller);
        (bool putSuccess,) = address(c).call{value: putAmount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        vm.assume(putSuccess);

        // Perform Collect from caller
        vm.prank(caller);
        (bool collectSuccess,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After Collect, the caller's balance in the mapping should never underflow
        // Since we cannot read the mapping directly (it has a public getter), we check that the balance is not negative
        // (uint has no negative, but underflow would cause a very large number; we check it's <= original deposit + putAmount)
        uint256 balanceAfter = c.Acc(caller).balance;
        // The balance should be at most the amount put (since we can only withdraw what was deposited plus any extra from contract balance)
        assertTrue(balanceAfter <= putAmount + address(c).balance, "Balance should not underflow");
    }
}

