import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(unlockTime <= type(uint256).max - 1); // avoid overflow in time check
        vm.assume(putAmount > 0 && putAmount < 100 ether);
        vm.assume(collectAmount >= 0 && collectAmount <= putAmount);
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);
        // Record contract ether balance and caller's account balance before Collect
        uint contractBalanceBefore = address(c).balance;
        (uint unlockBefore, uint accBalanceBefore) = c.Acc(caller);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        uint contractBalanceAfter = address(c).balance;
        (uint unlockAfter, uint accBalanceAfter) = c.Acc(caller);
        // If Collect did not transfer ether (no underflow, condition holds), contract balance should decrease by collectAmount
        if (success && collectAmount > 0 && accBalanceBefore >= 1 ether && accBalanceBefore >= collectAmount && block.timestamp > unlockBefore) {
            assertTrue(contractBalanceAfter == contractBalanceBefore - collectAmount, "Contract balance should decrease by collectAmount");
        } else {
            // Otherwise, no ether transferred, contract balance unchanged
            assertTrue(contractBalanceAfter == contractBalanceBefore, "Contract balance unchanged");
        }
    }
}

