        // Now fast forward
        vm.warp(laterTime);
        // Try Collect
        (bool collectOk,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        if (collectOk) {
            // After successful Collect, the actual unlockTime for the caller must be >= the expected value
            // Expected unlockTime = max(initialUnlockTime, putUnlockTime, block.timestamp at Put time)
            // But we cannot read block.timestamp at Put directly; we can use the fact that reference C sets it to max(putUnlockTime, block.timestamp)
            // Actually, we know block.timestamp at Put time is the timestamp at that time. We can store it.
            // However, we can reason: the reference contract's Put sets unlockTime = max(_unlockTime, block.timestamp)
            // Since we deployed c at time 0, block.timestamp is 0 initially. The test does not advance time before Put,
