            (uint256 actualUnlock,) = c.Acc(address(this));
            assertTrue(actualUnlock >= expectedUnlock, "Bug: unlockTime too small");
        }
        // If Collect failed, we don't assert (the rule only applies when Collect succeeds)
    }
}

